import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        # Validate HMAC signature of the key
        parts = api_key.split(':')
        if len(parts) != 2:
            return jsonify({'error': 'Invalid key format'}), 401
        key_id, signature = parts
        expected = hmac.new(SECRET_KEY.encode(), key_id.encode(), hashlib.sha256).hexdigest()[:16]
        if not hmac.compare_digest(signature, expected):
            return jsonify({'error': 'Invalid API key'}), 403
        return f(*args, **kwargs)
    return decorated

@app.route('/api/v2/users/search', methods=['GET'])
@require_api_key
def search_users():
    """Search users by various fields. Supports partial matching."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build dynamic query based on provided parameters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    if not conditions:
        return jsonify({'error': 'At least one search parameter required'}), 400

    where_clause = ' AND '.join(conditions)
    query = f"SELECT id, username, email, department, role FROM users WHERE {where_clause}"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Internal server error'}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    """Get user by ID."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v2/users/<int:user_id>/password-hash', methods=['GET'])
@require_api_key
def get_password_hash(user_id):
    """Admin endpoint to retrieve password hash for migration purposes."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, password_hash FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
